import {ProgressSync} from './sync.js';
import {SOLUTIONS} from './solutions.js';
import {EDITIONS} from './official.js';
import {EXAM_EDITIONS} from './uploaded-exams.js';
import {PRACTICE_SETS} from './practice.js';
import {AREAS,QUESTIONS,BY_ID,isPlayableId} from './questions.js';
import {planFor,remaining,phaseAt,selectQuestions,miniQuestions,scoreSession,emptyState,complete,questionPool,migrateSeen,markSeen,migrateContent,migrateStrategy,questionTime,settleQuestionTime,focusQuestion} from './core.js';
const KEY='fatec-prep-2027-v1';
const localProgress = document.body.dataset.progress === "local";
let progressSync=null;
let storageError=false,state=emptyState(),lastTimingSave=0;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&Array.isArray(saved.history)&&saved.mistakes&&typeof saved.mistakes==='object'){state={...emptyState(),...saved};if(state.active&&!state.active.qids.every(id=>BY_ID[id]))state.active=null;}}catch{storageError=true;}
if(state.active)state.active.questionClock=null;
const contentChanged=migrateContent(state),strategyChanged=migrateStrategy(state);
if(contentChanged||strategyChanged)persist();
let view='home',resultId=null,area='all',questionCount=10,minutes=20,reviewFilter='all',errorArea='all',toastTimeout;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const letter=n=>n===null||n===undefined?'Em branco':'ABCDE'[n];
const time=ms=>{const sec=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(sec/3600)?String(Math.floor(sec/3600)).padStart(2,'0')+':':''}${String(Math.floor(sec%3600/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;};
const shortTime=ms=>`${Math.floor(ms/60000)}min${Math.floor(ms/1000)%60?' '+Math.floor(ms/1000)%60+'s':''}`;
const date=ts=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(ts);
const areaOf=id=>AREAS.find(a=>a.id===id);
const editionOf=id=>EDITIONS.find(e=>e.id===id);
const trainOptions=()=>({source:state.trainingSource??'exam',edition:state.trainingEdition??null,area,seen:state.seen});
const simOptions=()=>({source:state.simEdition==='author'?'author':state.simEdition==='mixed'?'all':EXAM_EDITIONS.some(e=>e.id===state.simEdition)?'exam':'practice',edition:['author','mixed'].includes(state.simEdition)?null:(state.simEdition??'2026-2'),seen:state.seen});
const setLabel=id=>[...EXAM_EDITIONS,...PRACTICE_SETS].find(e=>e.id===id)?.label??(id==='mixed'?'Treino misto · 580 questões':'Banco inicial · 60 questões');
const richBlocks=blocks=>`<div class="rich-content">${blocks.map(b=>b.type==='html'?b.html:`<figure><a class="figure-link" href="${esc(b.src)}" target="_blank" rel="noopener noreferrer" aria-label="Ampliar figura"><img src="${esc(b.src)}" alt="${esc(b.alt)}" width="${b.width}" height="${b.height}" loading="lazy" style="max-width:min(100%,${b.displayWidth??Math.round(b.width/2.3)}px)"></a><figcaption>Toque para ampliar</figcaption></figure>`).join('')}</div>`;
const stemHTML=q=>q.content?richBlocks(q.content):`<p class="question-text">${esc(q.text)}</p>${tableHTML(q)}`;
const optionHTML=(q,i)=>q.optionContent?richBlocks(q.optionContent[i]):esc(q.options[i]);

const colors=['#a8bd83','#476b52','#cbac70','#849b72','#c2d6a0'];
const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v15',flag:'M5 22V3c5-4 9 4 14 0v11c-5 4-9-4-14 0',route:'M5 4h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h10M16 17l3 3-3 3M5 1v6',arrow:'M4 12h16M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L20 5',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',calendar:'M4 5h16v16H4zM7 2v6M17 2v6M4 10h16',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4M12 14v3',play:'m8 4 13 8-13 8V4',pause:'M8 4v16M16 4v16',refresh:'M20 8a9 9 0 1 0 1 7M20 2v6h-6',chart:'M4 20V4M4 20h17M9 16v-5M14 16V7M19 16v-8',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const btn=(label,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function persist(){settleQuestionTime(state.active);lastTimingSave=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageError=true;}progressSync?.touch();}
function syncQuestionFocus(){const s=state.active;if(!s)return;const id=view==='session'&&s.tab==='questions'&&!s.pausedAt&&!document.hidden?s.qids[s.current]:null;focusQuestion(s,id);}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function ask(title,message,ok='Encerrar sessão'){const d=$('#confirm-dialog');$('#dialog-title').textContent=title;$('#dialog-message').textContent=message;$('#dialog-ok').textContent=ok;d.returnValue='';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
function navigate(next){view=next;reviewFilter='all';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function shell(content){
 const names={home:'Visão geral',train:'Treino por área',strategy:'Estratégia de prova',errors:'Caderno de erros',session:'Sessão em andamento',result:'Resultado da sessão'};
 const mistakes=Object.keys(state.mistakes).filter(isPlayableId).length;
 return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="home"><span class="brand-mark">F</span><span><strong>Plano de prova</strong><small>FATEC · INGRESSO 2027</small></span></a><nav aria-label="Navegação principal"><div class="nav-label">SEU ESPAÇO DE ESTUDO</div>${[['home','home','Visão geral'],['train','book','Treino por área'],['strategy','route','Estratégia'],['errors','flag','Caderno de erros']].map(([v,i,n])=>`<button class="nav-item ${view===v?'active':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}${n}${v==='errors'&&mistakes?`<span class="count-badge">${mistakes}</span>`:''}</button>`).join('')}${state.active?`<button class="nav-item ${view==='session'?'active':''}" data-action="nav" data-view="session">${icon('clock')}Retomar sessão</button>`:''}</nav><div class="goals"><span class="eyebrow muted" style="color:#8fa695">SEU DESTINO</span><div class="goal"><span class="order">01 · Primeira opção</span>Análise e Desenvolvimento<br>de Sistemas<small>Período da manhã</small></div><div class="goal"><span class="order">02 · Segunda opção</span>Desenvolvimento de Software Multiplataforma<small>Período da tarde</small></div></div><div class="sidebar-foot">${icon('lock')}Seu espaço pessoal</div></aside><div class="layout"><header class="topbar"><div class="breadcrumb">Preparação 2027 <span>/</span><strong>${names[view]||''}</strong></div><div class="profile"><span id="sync-status"></span><span>andrezon</span><span class="avatar">AD</span></div></header><main id="main" tabindex="-1">${storageError?'<div class="storage-error" role="alert">O navegador não permitiu salvar seu progresso. Mantenha esta página aberta; o histórico desta sessão pode se perder ao sair.</div>':''}${state.active&&view!=='session'?`<div class="note" style="margin-bottom:20px">Uma sessão está ${state.active.pausedAt?'pausada':'em andamento; o relógio continua'}. <button class="text-button" data-action="nav" data-view="session">Retomar agora ${icon('arrow')}</button></div>`:''}<div id="sync-alert"></div>${content}<footer class="footnote"><div>400 questões de provas enviadas + 180 autorais · sem vínculo com o CPS.<br>${localProgress?'Progresso salvo neste navegador.':'Salvamento na conta e cópia neste navegador. <button class="text-button" data-action="sync-backups">Recuperar cópia</button>'}</div><span><a href="https://vestibular.fatec.sp.gov.br/documentos/" target="_blank" rel="noopener noreferrer">Manual 2027 ↗</a><a href="https://vestibular.fatec.sp.gov.br/provas-gabaritos/" target="_blank" rel="noopener noreferrer">Provas oficiais ↗</a></span></footer></main></div>`;
}
function heading(eyebrow,title,subtitle,badge=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${badge}</div>`;}
function timeline(plan){return `<div class="mini-timeline" aria-hidden="true">${plan.map((p,i)=>`<span style="flex:${p.minutes};background:${colors[i]}"></span>`).join('')}</div>`;}
function areaStats(id){const rows=state.history.flatMap(h=>h.score.rows).filter(r=>!r.cancelled&&BY_ID[r.id]?.area===id);return rows.length?`${Math.round(rows.filter(r=>r.correct).length/rows.length*100)}% de acerto`:'Ainda não treinada';}
function home(){
 const all=state.history.flatMap(h=>h.score.rows).filter(r=>!r.cancelled),correct=all.filter(r=>r.correct).length;
 const days=Math.max(0,Math.ceil((new Date('2026-12-13T00:00:00-03:00')-new Date(new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})+'T00:00:00-03:00'))/86400000));
 const plan=planFor(state.order);
 return `${heading('SEU PLANO, UM PASSO POR VEZ','Uma sessão de cada vez.','Treine o conteúdo. Acerte o ritmo. Chegue com uma estratégia.',`<span class="pill green"><span class="dot"></span>Preparação para 13 de dezembro</span>`)}<div class="mobile-goals"><strong>1ª opção:</strong> ADS · Manhã<br><strong>2ª opção:</strong> Desenvolvimento de Software Multiplataforma · Tarde</div><div class="hero-grid"><section class="start-card"><span class="eyebrow">SEU PRÓXIMO TREINO</span><h2>20 minutos.<br>Um pouco mais perto.</h2><p>10 questões por rodada, com enunciados completos e prioridade para as ainda não vistas.</p>${btn(`Começar treino ${icon('arrow')}`,'quick')}
 <svg class="start-graphic" viewBox="0 0 180 200" aria-hidden="true"><g fill="none" stroke="#92aa7a" stroke-width="1"><circle cx="105" cy="87" r="66"/><circle cx="105" cy="87" r="46"/><circle cx="105" cy="87" r="25"/><path d="m75 115 68-62M124 53h19v19" stroke-width="2"/><path d="M15 170h150M36 170v-22h23v22M69 170v-38h23v38M102 170v-54h23v54M135 170v-74h23v74"/></g><circle cx="105" cy="87" r="4" fill="#6f8c52"/></svg></section><section class="card date-card" aria-label="Data da prova"><div class="date-top"><span class="eyebrow">CONTAGEM REGRESSIVA</span>${icon('calendar')}</div><div class="date-number">${days}<small>dias para a prova</small></div><div class="date-bottom"><strong>13 de dezembro de 2026</strong><br><span>Domingo · 13h às 18h</span></div></section></div><div class="stats"><div class="card stat"><span class="stat-icon">${icon('check')}</span><div><div class="stat-value">${all.length}</div><div class="stat-label">Respostas corrigidas</div></div></div><div class="card stat"><span class="stat-icon">${icon('target')}</span><div><div class="stat-value">${all.length?Math.round(correct/all.length*100)+'%':'—'}</div><div class="stat-label">Acerto acumulado</div></div></div><div class="card stat"><span class="stat-icon">${icon('clock')}</span><div><div class="stat-value">${Math.floor(state.history.reduce((n,h)=>n+h.elapsedMs,0)/60000)}<span style="font-size:12px;letter-spacing:0"> min</span></div><div class="stat-label">Tempo em sessões concluídas</div></div></div></div><div class="dashboard-bottom"><section><div class="section-head"><div><h2>Escolha uma área</h2><p>Reforce a base e acompanhe seus acertos.</p></div></div><div class="area-grid">${AREAS.map(a=>`<button class="area-tile" data-action="area" data-area="${a.id}"><span class="area-monogram" style="background:${a.color}12;color:${a.color}">${a.short}</span><span><span class="area-name">${a.name}</span><span class="area-meta">${questionPool({area:a.id}).length} questões · ${areaStats(a.id)}</span></span>${icon('chevron')}</button>`).join('')}</div></section><section><div class="section-head"><h2>Além do conteúdo</h2></div><div class="card strategy-teaser"><span class="eyebrow">ESTRATÉGIA DE EXECUÇÃO</span><h3>O relógio também<br>faz parte da prova.</h3><p>${state.order==='draft-first'?'Comece pelo rascunho, resolva questões e volte à redação para passar a limpo com tempo reservado.':'Ensaie quando avançar, escrever a redação e passar as respostas para o gabarito.'}</p>${timeline(plan)}<div class="stage-labels">${plan.map((p,i)=>`<div><i style="background:${colors[i]}"></i>${p.name}<strong>${p.minutes} min</strong></div>`).join('')}</div><button class="text-button" data-action="nav" data-view="strategy">Montar meu ensaio ${icon('arrow')}</button></div></section></div>${archivePanel()}<section class="history"><div class="section-head"><h2>Sessões recentes</h2><span class="small muted">${state.history.length} concluídas</span></div>${state.history.length?`<div class="card">${state.history.slice(0,5).map(h=>`<div class="history-row"><span class="stat-icon">${icon(h.mode==='simulation'?'route':'book')}</span><div><strong>${esc(h.name)}</strong><small>${date(h.ended)} · ${shortTime(h.elapsedMs)}${h.expired?' · Tempo esgotado':''}</small></div><span class="score">${h.score.correct}/${h.score.scorable??h.score.total}</span>${btn('Revisar','history','secondary slim',`data-id="${h.id}"`)}</div>`).join('')}</div>`:`<div class="empty">${icon('chart')}<h3>Seu ponto de partida está aqui.</h3><p>Conclua uma sessão para ver seu resultado e os pontos que merecem atenção.</p></div>`}</section>`;
}
function train(){const opts=trainOptions(),pool=questionPool(opts),unseen=pool.filter(q=>!state.seen[q.id]?.count).length;questionCount=Math.min(questionCount,pool.length);
 return `${heading('TREINO COM FOCO','O que vamos praticar?','Mais repertório, menos repetição: as questões ainda não vistas vêm primeiro.')}<div class="config-layout"><section class="card config-card"><form id="train-form"><label class="field">Conjunto de questões<select id="source-select" name="source">${[['exam','Provas FATEC enviadas · 400 questões'],['practice','Treinos autorais · 120 questões'],['author','Banco inicial · 60 questões'],['all','Todos os conjuntos · 580 questões']].map(([v,n])=>`<option value="${v}" ${opts.source===v?'selected':''}>${n}</option>`).join('')}</select></label>${opts.source!=='author'?`<label class="field">Treino<select id="edition-select" name="edition"><option value="">Todas as edições deste conjunto</option>${(opts.source==='exam'?EXAM_EDITIONS:opts.source==='all'?[...EXAM_EDITIONS,...PRACTICE_SETS]:PRACTICE_SETS).map(e=>`<option value="${e.id}" ${opts.edition===e.id?'selected':''}>${e.label} · ${e.count} questões</option>`).join('')}</select><small>As questões anuladas ficam fora do sorteio de treino. Os enunciados e as alternativas aparecem completos na tela.</small></label>`:''}<label class="field">Área de conhecimento<select id="area-select" name="area"><option value="all">Todas as áreas</option>${AREAS.map(a=>`<option value="${a.id}" ${area===a.id?'selected':''}>${a.name}</option>`).join('')}</select><small>${pool.length} disponíveis neste filtro · ${unseen} ainda não vistas.</small></label><div class="field-row"><label class="field">Quantidade de questões<input id="count-input" name="count" type="number" min="1" max="${pool.length}" value="${questionCount}" required></label><label class="field">Tempo da sessão (min)<input id="minutes-input" name="minutes" type="number" min="1" max="300" value="${minutes}" required></label></div><div class="note" style="margin-bottom:23px">O sorteio prioriza inéditas; depois, as menos vistas e há mais tempo. Se você pedir mais questões do que as inéditas restantes, parte da rodada será revisão. No caderno de erros, a repetição é intencional.</div><button class="button" type="submit">${icon('play')}Iniciar sessão</button></form></section><aside class="stack"><div class="card list-card"><span class="eyebrow muted">TUDO NA PRÓPRIA TELA</span><h3 style="margin-top:12px">Leia, responda e entenda.</h3><p class="small muted">400 questões dos sete arquivos enviados, com enunciados, textos de apoio e cinco alternativas na tela. Gráficos, tirinhas e expressões visuais aparecem junto ao texto.</p><p class="small muted" style="margin-top:10px">A correção usa os gabaritos oficiais, incluindo retificações. As questões incluem resolução comentada para consultar durante o treino ou após encerrar o ensaio. Os 180 exercícios autorais continuam disponíveis com explicações.</p></div><div class="card list-card"><h3>Sete provas anteriores</h3>${EXAM_EDITIONS.map(e=>`<div class="edition-links"><strong>${e.label}</strong><span>${e.count} questões${e.rectified?' · gabarito retificado':''}</span></div>`).join('')}<p class="small muted" style="margin-top:12px">399 questões válidas para treino e uma anulada, preservada no ensaio da edição 2023/2.</p></div></aside></div>`;
}
function strategy(){const plan=planFor(state.order);return `${heading('CONTEÚDO + GESTÃO DO TEMPO','Ensaie o dia da prova.','Uma sugestão de ritmo para testar e ajustar ao seu jeito de resolver.')}<div class="config-layout"><section class="card config-card"><label class="field">Treino do ensaio<select id="simulation-edition">${[...EXAM_EDITIONS.map(e=>[e.id,`${e.label} · ${e.count} questões`]),...PRACTICE_SETS.map(e=>[e.id,e.label]),['mixed','Misto · sorteio entre 580 questões'],['author','Banco inicial · 60 questões']].map(([v,n])=>`<option value="${v}" ${(state.simEdition??'2026-2')===v?'selected':''}>${n}</option>`).join('')}</select><small>Edições de 2026 têm 60 questões; 2025/2 tem 64; edições de 2023 e 2024 têm 54. O ensaio preserva o caderno escolhido.</small></label><span class="eyebrow muted">ESCOLHA SUA ORDEM</span><div class="choice-grid"><button class="choice ${state.order==='draft-first'?'selected':''}" data-action="order" data-order="draft-first" aria-pressed="${state.order==='draft-first'}"><strong>Rascunho primeiro · recomendado</strong><small>Rascunhe, resolva questões e volte para revisar e passar a limpo.</small></button><button class="choice ${state.order==='questions'?'selected':''}" data-action="order" data-order="questions" aria-pressed="${state.order==='questions'}"><strong>Questões primeiro</strong><small>Resolva a primeira passada e depois escreva a redação.</small></button></div><div class="section-head" style="margin:26px 0 0"><h3>Seu roteiro de 5 horas</h3><span class="pill">300 min</span></div>${timeline(plan)}<div class="plan-list">${plan.map((p,i)=>`<div class="plan-item"><span class="plan-index">${i+1}</span><div><strong>${p.name}</strong><p>${p.tip}</p></div><span class="plan-minutes">${p.minutes} min</span></div>`).join('')}</div><p class="small muted" style="margin-top:18px">Os blocos são sugestões. O cronômetro indica a etapa do roteiro; você pode alternar entre questões, redação e gabarito a qualquer momento.</p></section><aside class="stack strategy-aside"><div class="card list-card"><span class="eyebrow muted">COMECE PELO ENSAIO RÁPIDO</span><h2 style="margin:12px 0">A estratégia em 30 minutos.</h2><p class="small muted">12 questões do treino escolhido, de todas as áreas, rascunho curto, versão definitiva e transferência manual para o gabarito. No roteiro recomendado: 4min30 de rascunho, 10min de questões, 3min para passar a limpo, 9min30 de revisão e 3min de gabarito.</p><div style="margin-top:22px">${btn(`${icon('play')}Ensaio de 30 min`,'simulate-mini')}</div></div><div class="card list-card"><h3>Ensaio de 5 horas</h3><p class="small muted">Todas as questões da edição escolhida, proposta de redação e gabarito. O relógio segue mesmo ao fechar a página; não há pausa.</p><div style="margin-top:17px">${btn('Começar ensaio completo','simulate-full','secondary')}</div></div><div class="note amber"><strong>Treino, sem previsão de aprovação.</strong><p>O exame oficial tem 60 questões e redação. Os percentuais medem os itens válidos deste treino, sem os pesos da seleção oficial. ADS e DSM usam a mesma preparação geral.</p></div></aside></div>`;}
function tableHTML(q){return q.table?`<div class="question-data"><table><caption>${esc(q.table.caption)}</caption><thead><tr>${q.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${q.table.rows.map(row=>`<tr>${row.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
function archivePanel(){const sessions=state.archivedSessions??[],errors=Object.values(state.legacyMistakes??{});if(!sessions.length&&!errors.length)return '';return `<details class="card list-card" style="margin:20px 0"><summary style="font-size:12px;cursor:pointer">Registros preservados da versão anterior (${sessions.length} sessões em andamento; ${errors.length} erros)</summary><p class="small muted" style="margin:15px 0">Os registros anteriores continuam guardados, com seus IDs e respostas originais. Eles ficam separados dos novos exercícios para manter a correção e o histórico consistentes.</p>${sessions.map(a=>`<details class="list-card"><summary class="small">${esc(a.name)} · ${Object.keys(a.answers).length}/${a.qids.length} respostas</summary><div class="small" style="white-space:pre-wrap;margin-top:15px"><strong>${esc(a.essay?.title)||'Rascunho sem título'}</strong><p>${esc(a.essay?.body)||'Sem texto de redação.'}</p><p class="muted">Marcações preservadas: ${a.qids.map((id,i)=>`${i+1}: ${letter(a.answers[id])}`).join(' · ')}</p></div></details>`).join('')}${errors.length?`<div class="small muted">${errors.map(m=>`${esc(BY_ID[m.id]?.topic??m.id)} — resposta: ${letter(m.answer)}`).join('<br>')}</div>`:''}</details>`;}

function explanationHTML(q,answer){
 const solution=SOLUTIONS[q.id],reason=solution?.explanation??q.explanation;
 const title=q.cancelled?'Questão anulada':answer==null?'Como resolver esta questão':answer===q.correct?'Por que você acertou':'Por que essa resposta está incorreta';
 return `<div class="answer-explanation"><h3>${title}</h3>${q.cancelled?'':`<p class="small">Sua resposta: <strong>${letter(answer)}</strong> · Correta: <strong>${letter(q.correct)}</strong></p><div class="explanation-correct"><strong>Alternativa ${letter(q.correct)}</strong>${optionHTML(q,q.correct)}</div>`}<p class="solution-text">${esc(reason)}</p>${solution?.optionNotes?.[answer]?`<p>${esc(solution.optionNotes[answer])}</p>`:''}${q.source==='exam'?`<p class="tiny muted">Resolução de estudo · resposta conferida no gabarito oficial${EXAM_EDITIONS.find(e=>e.id===q.edition)?.rectified?' retificado':''}.</p>`:''}</div>`;
}
function trainingFeedback(s,q){if(s.mode==='simulation')return '<p class="tiny muted">As explicações ficam disponíveis na revisão, após encerrar o ensaio.</p>';return `${btn('Conferir e explicar minha resposta','explain-answer','secondary',s.answers[q.id]===undefined?'disabled':'')}<p class="tiny muted" style="margin-top:8px">Ao abrir a explicação, esta tentativa será identificada como estudo com ajuda.</p><div id="inline-explanation">${s.revealed?.[q.id]&&s.answers[q.id]!==undefined?explanationHTML(q,s.answers[q.id]):''}</div>`;}
function questionPanel(s){const q=BY_ID[s.qids[s.current]],a=areaOf(q.area),ans=s.answers[q.id];
 return `<div class="session-layout"><section class="card question-card"><div class="question-head"><span class="topic">${a.name} · ${q.topic}<br>Questão ${s.current+1} de ${s.qids.length}</span><button class="flag-button ${s.flags[q.id]?'flagged':''}" data-action="flag" aria-pressed="${!!s.flags[q.id]}">${icon('flag')}${s.flags[q.id]?'Marcada':'Marcar dúvida'}</button></div><div class="question-timing">${icon('clock')}<span>Tempo ativo nesta questão <strong id="question-timer" role="timer" aria-label="Tempo ativo nesta questão">${time(questionTime(s,q.id))}</strong></span><small>Acumula nas revisitas · pausa fora desta questão</small></div><div id="question-text" tabindex="-1">${q.content?`<p class="question-origin">Original · ${esc(setLabel(q.edition))} · questão ${q.number} · página ${q.page}</p>`:''}${stemHTML(q)}${q.cancelled?'<div class="note amber">Questão anulada no gabarito oficial. Preservada no caderno, sem efeito no percentual nem no caderno de erros.</div>':''}</div><fieldset class="answers"><legend class="sr-only">Escolha uma alternativa</legend>${q.options.map((o,i)=>`<label class="answer ${ans===i?'selected':''}"><input type="radio" id="answer-${i}" name="answer" value="${i}" ${ans===i?'checked':''}><span class="letter">${letter(i)}</span><span class="answer-content">${optionHTML(q,i)}</span></label>`).join('')}</fieldset><div class="training-feedback">${trainingFeedback(s,q)}</div><div class="question-actions">${btn('Anterior','prev','secondary',s.current===0?'disabled':'')}<button class="text-button" data-action="clear-answer" ${ans===undefined?'disabled':''}>Limpar resposta</button>${btn(s.current===s.qids.length-1?'Ir ao mapa':'Próxima '+icon('arrow'),'next','',s.current===s.qids.length-1?'data-last="true"':'')}</div><p class="tiny muted" style="margin-top:17px">Teclado: 1–5 para responder · ← → para navegar · M para marcar.</p></section><aside class="card navigator" id="question-map"><h3>Seu mapa de questões</h3><div class="q-grid">${s.qids.map((id,i)=>`<button class="q-number ${s.answers[id]!==undefined?'answered':''} ${i===s.current?'current':''} ${s.flags[id]?'flagged':''}" data-action="goto" data-index="${i}" aria-label="Questão ${i+1}${s.answers[id]!==undefined?', respondida':''}${s.flags[id]?', marcada para revisar':''}" ${i===s.current?'aria-current="true"':''}>${i+1}</button>`).join('')}</div><div class="legend"><span><i class="done"></i>${Object.keys(s.answers).length} respondidas</span><span><i></i>${s.qids.length-Object.keys(s.answers).length} em branco</span><span><i class="marked"></i>${Object.values(s.flags).filter(Boolean).length} para revisar</span></div>${btn('Próxima dúvida / em branco','next-pending','secondary')}${btn('Encerrar sessão','finish')}</aside></div>`;
}
function essayPanel(s){const proposal=EXAM_EDITIONS.find(e=>e.id===s.examEdition)?.essay??PRACTICE_SETS.find(e=>e.id===s.examEdition)?.essay??{title:'Tecnologia e inclusão no cotidiano',prompt:'Produza uma dissertação em prosa, com título, sobre os desafios para que a digitalização de serviços amplie o acesso da população. Desenvolva uma posição com argumentos e exemplos, considerando conectividade, acessibilidade e letramento digital.'};return `<section class="card essay-card"><span class="eyebrow muted">${proposal.content?'PROPOSTA ORIGINAL · '+esc(setLabel(s.examEdition)):'PROPOSTA AUTORAL · DISSERTAÇÃO'}</span><h2 style="margin-top:12px">${esc(proposal.title)}</h2>${proposal.content?richBlocks(proposal.content):`<p>${esc(proposal.prompt)}</p>`}<div class="note" style="margin-top:17px">${s.durationMs===1800000?'No ensaio rápido, escreva um rascunho curto e depois ensaie a transcrição.':(s.plan?.some(p=>p.id==='essay-draft')?'Faça o rascunho no primeiro bloco. Depois da primeira passada nas questões, volte para revisar e passar a limpo.':'No bloco de redação do seu roteiro, escreva o rascunho, revise e transcreva a versão definitiva.')} O texto é salvo neste navegador e sincronizado na sua conta. Não há correção automática nem nota de redação.</div><div class="essay-fields"><label class="field">Título<input id="essay-title" type="text" maxlength="200" value="${esc(s.essay.title)}" placeholder="Dê um título ao seu texto"></label><label class="field">Rascunho<textarea id="essay-draft" placeholder="Leia a proposta, organize as ideias e escreva o rascunho completo…">${esc(s.essay.draft??'')}</textarea></label><div class="essay-counters" id="draft-counters">${essayCounts(s.essay.draft??'')}</div><div class="note">Volte aqui no bloco de transcrição: releia o rascunho, faça ajustes e reescreva a versão definitiva no campo abaixo.</div><label class="field">Versão definitiva · passar a limpo<textarea id="essay-body" placeholder="Reescreva seu texto revisado para ensaiar a versão que será entregue…">${esc(s.essay.body)}</textarea></label><div class="essay-counters" id="essay-counters">${essayCounts(s.essay.body)}</div></div><h3>Conferência do texto</h3><div class="checklist">${['Respondi ao tema e ao gênero solicitado.','Meu texto tem título, ideias organizadas e argumentos claros.','Revisei concordância, pontuação e repetições.','Passei a redação a limpo e conferi a versão definitiva.'].map((text,i)=>`<label><input type="checkbox" data-essay-check="${i}" ${s.essay.checks[i]?'checked':''}>${text}</label>`).join('')}</div></section>`;}
function essayCounts(body=''){return `<span>${body.trim()?body.trim().split(/\s+/).length:0} palavras</span><span>${body.length} caracteres</span><span>Contagem de linhas digitais não equivale à folha oficial.</span>`;}
function sheetPanel(s){return `<section class="card sheet-card"><span class="eyebrow muted">TRANSFERÊNCIA MANUAL</span><h2 style="margin:10px 0">A última etapa também conta.</h2><p class="small muted">Confira cada alternativa anotada no caderno e marque no gabarito abaixo. No ensaio, a correção usa <strong>somente este gabarito</strong>. As anotações do caderno não são transferidas automaticamente.</p><div class="sheet-grid">${s.qids.map((id,n)=>`<div class="sheet-row"><strong>${String(n+1).padStart(2,'0')}</strong>${[0,1,2,3,4].map(i=>`<label class="sheet-option ${s.sheet[id]===i?'checked':''}"><input type="radio" name="sheet-${id}" value="${i}" data-qid="${id}" aria-label="Questão ${n+1}, alternativa ${letter(i)}" ${s.sheet[id]===i?'checked':''}>${letter(i)}</label>`).join('')}<small>Caderno: ${s.answers[id]===undefined?'—':letter(s.answers[id])}</small><button class="text-button" data-action="clear-sheet" data-id="${id}" aria-label="Limpar questão ${n+1} do gabarito">×</button></div>`).join('')}</div><div class="button-row" style="margin-top:25px">${btn('Encerrar e corrigir','finish')}<span class="small muted">${Object.keys(s.sheet).length}/${s.qids.length} transferidas</span></div></section>`;}
function phaseHTML(s){const p=phaseAt(s);return `${icon('route')}<div><strong>Etapa ${p.index+1}/${s.plan.length} · ${p.name}</strong><p>${p.tip}</p>${p.target?`<button class="text-button" data-action="phase-go" data-tab="${p.target}" ${p.focus?`data-focus="${p.focus}"`:''}>${p.id==='essay-draft'?'Ir ao rascunho':p.id==='essay-final'?'Passar a limpo':p.target==='sheet'?'Ir ao gabarito':'Ir às questões'} ${icon('arrow')}</button>`:''}</div><span class="phase-time">${time(p.remaining)} nesta etapa</span>`;}

function session(){const s=state.active;if(!s)return '<div class="empty"><h3>Nenhuma sessão em andamento.</h3><p>Escolha um treino para começar.</p></div>';
 return `<div class="session-bar"><div><div class="session-name">${esc(s.name)}</div><div class="session-meta">${s.mode==='simulation'?'Ensaio sem pausa · correção pelo gabarito':'Treino · correção ao encerrar'}</div></div><div class="timer-controls"><div><div class="timer" id="session-timer" role="timer" aria-label="Tempo restante">${icon('clock')}<span>${time(remaining(s))}</span></div><div class="timer-caption">${s.pausedAt?'PAUSADO':'TEMPO RESTANTE'}</div></div>${s.mode!=='simulation'?btn(icon(s.pausedAt?'play':'pause'),'pause','secondary slim',`aria-label="${s.pausedAt?'Retomar':'Pausar'} cronômetro"`):''}</div></div><div class="progress" aria-hidden="true"><span id="time-progress" style="width:${remaining(s)/s.durationMs*100}%"></span></div>${s.mode==='simulation'?`<div class="phase-banner" id="phase-banner">${phaseHTML(s)}</div><div class="tabs" role="group" aria-label="Partes do ensaio">${[['questions','Questões'],['essay','Redação'],['sheet','Gabarito']].map(([id,name])=>`<button class="tab ${s.tab===id?'active':''}" data-action="session-tab" data-tab="${id}" aria-pressed="${s.tab===id}">${name}${id==='sheet'?`<small>${Object.keys(s.sheet).length}/${s.qids.length}</small>`:''}</button>`).join('')}<button class="tab" style="margin-left:auto" data-action="finish">Encerrar</button></div>`:''}${s.pausedAt?`<div class="pause-overlay">${icon('pause')}<h2>Uma pausa para respirar.</h2><p>O cronômetro do treino está parado. Retome para continuar respondendo.</p>${btn(`${icon('play')}Retomar treino`,'pause')}</div>`:s.tab==='essay'?essayPanel(s):s.tab==='sheet'?sheetPanel(s):questionPanel(s)}`;
}
function reviewItem(row,n,open=false){const q=BY_ID[row.id];return `<details class="review-item ${row.correct?'correct':''}" ${open?'open':''}><summary><span class="status-icon">${row.cancelled?'—':row.correct?'✓':'×'}</span><span><span class="topic">${areaOf(q.area).name} · ${q.topic}</span><span class="review-time">${row.timeMs!=null?`Tempo ativo: ${time(row.timeMs)}`:'Tempo não registrado nesta sessão'}${row.assisted?' · Explicação consultada durante o treino':''}</span><strong>${n+1}. ${row.cancelled?'Anulada · sem pontuação':row.correct?'Resposta correta':row.answer===null?'Questão em branco':'Revisar resposta'}${row.flag?'<span class="inline-badge">Marcada</span>':''}</strong></span>${icon('chevron')}</summary><div class="review-body">${stemHTML(q)}${q.options.map((o,i)=>`<div class="review-option ${i===q.correct?'right':i===row.answer?'wrong':''}"><b>${letter(i)}</b>${optionHTML(q,i)}${i===q.correct?' <strong>· Correta</strong>':''}${i===row.answer?' · Sua resposta':''}</div>`).join('')}<details class="solution-disclosure"><summary>${row.cancelled?'Entender a anulação':row.answer==null?'Explicar esta questão':row.correct?'Explicar meu acerto':'Explicar meu erro'}</summary>${explanationHTML(q,row.answer)}</details></div></details>`;}
function result(){const h=state.history.find(h=>h.id===resultId)||state.history[0];if(!h)return home();const score=h.score;let rows=score.rows;if(reviewFilter==='wrong')rows=rows.filter(r=>!r.correct&&!r.cancelled);if(reviewFilter==='flagged')rows=rows.filter(r=>r.flag);const perArea=AREAS.map(a=>{const rs=score.rows.filter(r=>!r.cancelled&&BY_ID[r.id].area===a.id);return {...a,total:rs.length,correct:rs.filter(r=>r.correct).length};}).filter(a=>a.total);
 return `${heading(h.expired?'TEMPO ESGOTADO · SESSÃO ENCERRADA':'SESSÃO CONCLUÍDA','Agora vem a parte que ensina.',`${esc(h.name)} · ${date(h.ended)}`)}<div class="result-top"><div class="result-score"><div class="big">${score.correct}<small>/${score.scorable??score.total}</small></div><div><span class="eyebrow">ACERTOS NA PARTE OBJETIVA</span><p>${score.percent}% de acerto neste treino.${score.cancelled?` ${score.cancelled} anulada(s), sem pontuação.`:''}<br>Sem estimativa de nota final ou classificação.</p></div></div><div class="card result-info"><h3>${score.correct===(score.scorable??score.total)?'Boa rodada. Continue variando os desafios.':'Um erro revisto é um próximo passo.'}</h3><div class="result-metrics"><div><strong>${shortTime(h.elapsedMs)}</strong><span>Tempo usado</span></div><div><strong>${(score.scorable??score.total)-score.correct}</strong><span>Erros + em branco</span></div><div><strong>${score.blank}</strong><span>Em branco</span></div></div><div class="button-row">${score.rows.some(r=>!r.correct&&!r.cancelled&&isPlayableId(r.id))?btn(`${icon('refresh')}Refazer os erros`,'redo-result','',`data-id="${h.id}"`):btn('Novo treino','nav','',`data-view="train"`)}${btn('Voltar ao painel','nav','secondary',`data-view="home"`)}</div></div></div>${h.mode==='simulation'?`<div class="note ${score.mismatches?'amber':''}" style="margin-bottom:20px"><strong>Conferência da estratégia</strong><p>${Object.keys(h.answers).length}/${score.total} questões anotadas no caderno · ${Object.keys(h.sheet).length}/${score.total} no gabarito · ${score.mismatches} diferenças entre caderno e gabarito. A correção usa o gabarito.</p><p>Versão definitiva: ${h.essay.body.trim()?h.essay.body.trim().split(/\s+/).length:0} palavras · ${h.essay.checks.filter(Boolean).length}/4 itens de conferência. Sem correção automática.</p></div><details class="card list-card" style="margin-bottom:20px"><summary style="font-size:12px;cursor:pointer">Rever meu texto e o roteiro usado</summary><div style="margin-top:17px"><h3>Rascunho</h3><p class="small" style="white-space:pre-wrap;margin:12px 0">${esc(h.essay.draft)||'Sem rascunho salvo.'}</p><h3>Versão definitiva</h3><strong class="small">${esc(h.essay.title)||'Sem título'}</strong><p class="small" style="white-space:pre-wrap;margin:12px 0">${esc(h.essay.body)||'Você não escreveu nesta sessão.'}</p><p class="small muted">${h.plan.map(p=>`${p.name}: ${Number(p.minutes.toFixed(1))} min`).join(' · ')}</p></div></details>`:''}${score.assisted?`<div class="note amber" style="margin-bottom:20px">${score.assisted} questão(ões) com explicação consultada durante o treino. Este resultado inclui estudo com ajuda.</div>`:''}<section class="card list-card" style="margin-bottom:28px"><h3>Onde concentrar a próxima sessão</h3><div class="areas-result">${perArea.map(a=>`<div class="area-result-row"><span>${a.name}</span><div class="progress"><span style="width:${a.correct/a.total*100}%"></span></div><strong>${a.correct}/${a.total}</strong></div>`).join('')}</div></section><div class="review-tools"><h2 style="font-size:19px">Correção e revisão</h2><select id="review-filter" aria-label="Filtrar correção"><option value="all" ${reviewFilter==='all'?'selected':''}>Todas (${score.total})</option><option value="wrong" ${reviewFilter==='wrong'?'selected':''}>Erros e brancos (${(score.scorable??score.total)-score.correct})</option><option value="flagged" ${reviewFilter==='flagged'?'selected':''}>Marcadas (${score.rows.filter(r=>r.flag).length})</option></select></div><div class="review-list">${rows.length?rows.map(r=>reviewItem(r,score.rows.indexOf(r))).join(''):'<div class="empty"><p>Nenhuma questão neste filtro.</p></div>'}</div>`;
}
function errors(){const all=Object.values(state.mistakes).filter(m=>isPlayableId(m.id));const filtered=all.filter(m=>errorArea==='all'||BY_ID[m.id].area===errorArea);return `${heading('REVISÃO QUE VIRA APRENDIZADO','Volte ao que ficou pelo caminho.','Erros e questões em branco ficam aqui até você acertá-los em outra sessão sem consultar a explicação.')}<div class="review-tools"><span class="small muted">${all.length} questões para retomar</span><select id="error-area" aria-label="Filtrar erros por área"><option value="all">Todas as áreas</option>${AREAS.map(a=>`<option value="${a.id}" ${errorArea===a.id?'selected':''}>${a.name}</option>`).join('')}</select></div>${filtered.length?`<div class="note" style="margin-bottom:20px;display:flex;gap:15px;align-items:center;justify-content:space-between;flex-wrap:wrap"><span>Uma nova tentativa, sem as respostas à vista.<br><small>Até 10 questões · 20 minutos</small></span>${btn(`${icon('refresh')}Treinar estes erros`,'redo-errors')}</div><div class="review-list">${filtered.map((m,i)=>reviewItem({...m,correct:false},i)).join('')}</div>`:`<div class="empty">${icon('flag')}<h3>${all.length?'Nenhum erro nesta área.':'Seu caderno está livre por enquanto.'}</h3><p>${all.length?'Escolha outra área ou faça uma nova rodada.':'Ao concluir um treino, os erros e as questões em branco aparecerão aqui com explicação.'}</p>${btn('Escolher um treino','nav','',`data-view="train"`)}</div>`}`;}
function render(focusId=null){syncQuestionFocus();const y=window.scrollY;const content=({home,train,strategy,session,result,errors}[view]||home)();$('#app').innerHTML=shell(content);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});window.scrollTo(0,y);}
function refreshQuestion(focusId=null){const s=state.active;if(!s||view!=='session'||s.tab!=='questions')return;const id=s.qids[s.current];document.querySelectorAll('input[name="answer"]').forEach(el=>{el.checked=s.answers[id]===Number(el.value);el.closest('.answer').classList.toggle('selected',el.checked);});const flag=$('[data-action="flag"]');if(flag){flag.classList.toggle('flagged',!!s.flags[id]);flag.setAttribute('aria-pressed',String(!!s.flags[id]));flag.innerHTML=icon('flag')+(s.flags[id]?'Marcada':'Marcar dúvida');}document.querySelectorAll('.q-number').forEach((el,i)=>{const qid=s.qids[i];el.classList.toggle('answered',s.answers[qid]!==undefined);el.classList.toggle('flagged',!!s.flags[qid]);el.setAttribute('aria-label',`Questão ${i+1}${s.answers[qid]!==undefined?', respondida':''}${s.flags[qid]?', marcada para revisar':''}`);});const explain=$('[data-action="explain-answer"]');if(explain)explain.disabled=s.answers[id]===undefined;const inline=$('#inline-explanation');if(inline)inline.innerHTML=s.revealed?.[id]&&s.answers[id]!==undefined?explanationHTML(BY_ID[id],s.answers[id]):'';const clear=$('[data-action="clear-answer"]');if(clear)clear.disabled=s.answers[id]===undefined;const legend=$('.navigator .legend');if(legend)legend.innerHTML=`<span><i class="done"></i>${Object.keys(s.answers).length} respondidas</span><span><i></i>${s.qids.length-Object.keys(s.answers).length} em branco</span><span><i class="marked"></i>${Object.values(s.flags).filter(Boolean).length} para revisar</span>`;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
async function start({mode='training',ids=null,count=10,area='all',mins=20,name='Treino misto',full=false,source=state.trainingSource??'exam',edition=state.trainingEdition??null}={}){
 if(state.active){navigate('session');notify('Encerre a sessão atual antes de começar outra.');return;}
 const qids=ids??selectQuestions({area,count,full,source,edition,seen:state.seen});if(!qids.length){notify('Não há questões disponíveis para este treino.');return;}
 const now=Date.now();markSeen(state,qids,now);const examEdition=qids.every(id=>BY_ID[id].edition===BY_ID[qids[0]].edition)?BY_ID[qids[0]].edition:null;state.active={id:globalThis.crypto?.randomUUID?.()??String(now),mode,name,qids,examEdition,current:0,questionTimes:{},questionClock:null,revealed:{},answers:{},sheet:{},flags:{},tab:mode==='simulation'&&state.order==='draft-first'?'essay':'questions',essay:{title:'',draft:'',body:'',checks:[false,false,false,false]},started:now,deadline:now+mins*60000,durationMs:mins*60000,pausedAt:null,plan:mode==='simulation'?planFor(state.order,mins):null};persist();navigate('session');
}
function end(expired=false){if(!state.active)return;const h=complete(state,Date.now(),expired);resultId=h.id;reviewFilter='wrong';persist();if($('#confirm-dialog').open)$('#confirm-dialog').close('cancel');view='result';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});if(expired)notify('Tempo esgotado. Sua sessão foi encerrada e corrigida.');}
async function finish(){const s=state.active;if(!s)return;const submitted=s.mode==='simulation'?s.sheet:s.answers;const blank=s.qids.filter(id=>!BY_ID[id].cancelled&&submitted[id]===undefined).length;const msg=`${s.mode==='simulation'&&s.essay.draft?.trim()&&!s.essay.body.trim()?'Você escreveu um rascunho, mas a versão definitiva está vazia. ':''}${blank?`${blank} questão(ões) ${s.mode==='simulation'?'sem marcação no gabarito':'em branco'} entrarão como erro. `:''}${s.mode==='simulation'?'A correção usará apenas o gabarito transferido. ':''}Depois de encerrar, você verá a correção. A revisão inclui explicações das respostas.`;if(await ask('Encerrar e ver a correção?',msg))end();}
document.addEventListener('submit',e=>{if(e.target.id!=='train-form')return;e.preventDefault();const f=new FormData(e.target);const a=String(f.get('area')),c=Number(f.get('count')),m=Number(f.get('minutes'));if(!Number.isInteger(c)||c<1||c>questionPool({...trainOptions(),area:a}).length||!Number.isInteger(m)||m<1||m>300)return;questionCount=c;minutes=m;start({area:a,count:c,mins:m,name:a==='all'?'Treino misto':`Treino · ${areaOf(a).name}`});});
document.addEventListener('click',async e=>{
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const act=el.dataset.action,s=state.active;
 if(act==='sync-now'){await progressSync.sync();}
 else if(act==='sync-cloud'){await progressSync.resolve('cloud');render();}
 else if(act==='sync-local'){await progressSync.resolve('local');render();}
 else if(act==='sync-backups'){await showSyncBackups();}
 else if(act==='restore-cloud'||act==='restore-local'){if(await ask('Recuperar esta cópia?', 'O progresso atual ficará guardado em uma cópia neste navegador. A versão recuperada será sincronizada na conta.', 'Recuperar')){try{await progressSync[act==='restore-cloud'?'restoreCloud':'restoreLocal'](Number(el.dataset.revision));$('#backup-dialog').close();render();}catch{notify('Não foi possível recuperar. Seu progresso atual foi preservado.');}}}
 else if(act==='nav'){e.preventDefault();navigate(el.dataset.view);}
 else if(act==='quick')start();
 else if(act==='area'){area=el.dataset.area;questionCount=Math.min(5,areaOf(area).count);navigate('train');}
 else if(act==='order'){state.order=el.dataset.order;persist();render();}
 else if(act==='simulate-mini')start({mode:'simulation',ids:miniQuestions(simOptions()),...simOptions(),mins:30,name:'Ensaio de estratégia · 30 min'});
 else if(act==='simulate-full'){if(state.active){navigate('session');return;}if(await ask('Começar o ensaio de 5 horas?','O cronômetro será contínuo, inclusive com a página fechada. Resolva as questões da edição escolhida, escreva e transfira as respostas para o gabarito.','Começar 5 horas'))start({mode:'simulation',full:true,...simOptions(),mins:300,name:`Ensaio completo · ${setLabel(state.simEdition)}`});}
 else if(act==='history'){resultId=el.dataset.id;navigate('result');}
 else if(act==='redo-result'){const h=state.history.find(h=>h.id===el.dataset.id);const ids=h.score.rows.filter(r=>!r.correct&&!r.cancelled&&isPlayableId(r.id)).map(r=>r.id);start({ids:selectQuestions({ids,count:10}),mins:20,name:'Revisão de erros'});}
 else if(act==='redo-errors'){const ids=Object.keys(state.mistakes).filter(id=>isPlayableId(id)&&(errorArea==='all'||BY_ID[id]?.area===errorArea));start({ids:selectQuestions({ids,count:10}),mins:20,name:'Revisão do caderno de erros'});}
 else if(!s)return;
 else if(act==='finish')finish();
 else if(act==='pause'&&s.mode!=='simulation'){if(s.pausedAt){s.deadline+=Date.now()-s.pausedAt;s.pausedAt=null;}else s.pausedAt=Date.now();persist();render();}
 else if(s.pausedAt)return;
 else if(act==='phase-go'){s.tab=el.dataset.tab;persist();render();if(el.dataset.focus)$('#'+el.dataset.focus)?.focus();}
 else if(act==='session-tab'){s.tab=el.dataset.tab;persist();render();}
 else if(act==='explain-answer'&&s.mode!=='simulation'){const id=s.qids[s.current];if(s.answers[id]===undefined)return;s.revealed??={};s.revealed[id]=true;persist();refreshQuestion();$('#inline-explanation')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 else if(act==='flag'){const id=s.qids[s.current];s.flags[id]=!s.flags[id];persist();refreshQuestion();}
 else if(act==='clear-answer'){delete s.answers[s.qids[s.current]];persist();refreshQuestion();}
 else if(act==='clear-sheet'){delete s.sheet[el.dataset.id];persist();render();}
 else if(act==='goto'||act==='prev'||act==='next'){if(act==='next'&&s.current===s.qids.length-1){$('#question-map').scrollIntoView({behavior:'smooth',block:'center'});$('#question-map button')?.focus({preventScroll:true});return;}s.current=act==='goto'?Number(el.dataset.index):Math.max(0,Math.min(s.qids.length-1,s.current+(act==='next'?1:-1)));persist();render();$('#question-text')?.focus({preventScroll:true});}
 else if(act==='next-pending'){const next=[...s.qids.slice(s.current+1),...s.qids.slice(0,s.current+1)].find(id=>s.flags[id]||s.answers[id]===undefined);if(next){s.current=s.qids.indexOf(next);persist();render();$('#question-text')?.focus({preventScroll:true});}else notify('Todas respondidas e nenhuma marcada. Você pode encerrar.');}
});
document.addEventListener('change',e=>{const el=e.target,s=state.active;
 if(el.id==='area-select'){area=el.value;render();}
 else if(el.id==='source-select'){state.trainingSource=el.value;state.trainingEdition=null;persist();render();}
 else if(el.id==='edition-select'){state.trainingEdition=el.value||null;persist();render();}
 else if(el.id==='simulation-edition'){state.simEdition=el.value;persist();render();}
 else if(el.id==='review-filter'){reviewFilter=el.value;render('review-filter');}
 else if(el.id==='error-area'){errorArea=el.value;render('error-area');}
 else if(s&&!s.pausedAt){
  if(el.name==='answer'){s.answers[s.qids[s.current]]=Number(el.value);persist();refreshQuestion(el.id);}
  else if(el.dataset.qid){s.sheet[el.dataset.qid]=Number(el.value);persist();const focused=`input[name="${el.name}"][value="${el.value}"]`;render();$(focused)?.focus({preventScroll:true});}
  else if(el.dataset.essayCheck!==undefined){s.essay.checks[Number(el.dataset.essayCheck)]=el.checked;persist();}
 }
});
document.addEventListener('input',e=>{const s=state.active;if(!s||s.pausedAt)return;if(e.target.id==='essay-title'){s.essay.title=e.target.value;persist();}if(e.target.id==='essay-draft'){s.essay.draft=e.target.value;persist();$('#draft-counters').innerHTML=essayCounts(s.essay.draft);}if(e.target.id==='essay-body'){s.essay.body=e.target.value;persist();$('#essay-counters').innerHTML=essayCounts(s.essay.body);}});
document.addEventListener('keydown',e=>{const s=state.active;if(!s||view!=='session'||s.pausedAt||s.tab!=='questions'||$('#confirm-dialog').open||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('textarea,select,input:not([type="radio"])'))return;
 if(/^[1-5]$/.test(e.key)){e.preventDefault();s.answers[s.qids[s.current]]=Number(e.key)-1;persist();refreshQuestion(`answer-${Number(e.key)-1}`);}
 else if(e.key.toLowerCase()==='m'){e.preventDefault();s.flags[s.qids[s.current]]=!s.flags[s.qids[s.current]];persist();refreshQuestion();}
 else if((e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();s.current=Math.max(0,Math.min(s.qids.length-1,s.current+(e.key==='ArrowRight'?1:-1)));persist();render();}
});
function tick(){const s=state.active;if(!s)return;if(!s.pausedAt&&remaining(s)<=0){end(true);return;}if(view!=='session')return;const timer=$('#session-timer');if(timer){timer.querySelector('span').textContent=time(remaining(s));timer.classList.toggle('urgent',remaining(s)<=60000);}const individual=$('#question-timer');if(individual)individual.textContent=time(questionTime(s,s.qids[s.current]));if(s.questionClock&&Date.now()-lastTimingSave>5000)persist();const progress=$('#time-progress');if(progress)progress.style.width=remaining(s)/s.durationMs*100+'%';const phase=$('#phase-banner');if(phase)phase.innerHTML=phaseHTML(s);}
document.addEventListener('visibilitychange',()=>{syncQuestionFocus();persist();if(!document.hidden)tick();});
window.addEventListener('pagehide',()=>{focusQuestion(state.active,null);persist();});
window.addEventListener('pageshow',()=>{syncQuestionFocus();tick();});
if(state.active&&!state.active.pausedAt&&remaining(state.active)<=0)end(true);else render();
setInterval(tick,500);

if (!localProgress) {
 progressSync=new ProgressSync({getState:()=>state,applyState:applyCloudState,storage:localStorage,onStatus:renderSyncStatus});
 progressSync.sync();
 setInterval(()=>{if(!document.hidden)progressSync.sync();},5000);
 window.addEventListener('online',()=>progressSync.sync());
 window.addEventListener('focus',()=>progressSync.sync());
 window.addEventListener('pagehide',()=>progressSync.sync());
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)progressSync.sync();});
 window.addEventListener('storage',e=>{if(e.key===KEY)progressSync.sync();});
}
function applyCloudState(next){
 state={...emptyState(),...next};if(state.active)state.active.questionClock=null;
 migrateContent(state);migrateStrategy(state);
 try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageError=true;}
 if(view==='session'&&!state.active)view='home';
 render();if(state.active&&!state.active.pausedAt&&remaining(state.active)<=0)end(true);
}
function renderSyncStatus(){
 if(!progressSync)return;
 const status=progressSync.status,kind=status.kind;
 const labels={loading:'Conectando…',pending:'Aguardando envio…',saving:'Salvando na conta…',synced:'Sincronizado',offline:'Sem sincronização · salvo aqui',signin:'Entrar para sincronizar','too-large':'Cópia grande demais · salva aqui','local-error':'Falha no salvamento local',conflict:'Revisar diferenças'};
 const node=$('#sync-status');if(node)node.innerHTML=kind==='signin'?'<a href="/signin-with-chatgpt?return_to=%2F" target="_top">Entrar para sincronizar</a>':`<button class="sync-status ${kind}" data-action="sync-now" title="${status.at?'Último envio confirmado: '+date(status.at)+'. ':''}Sincronizar agora">${esc(labels[kind]??labels.offline)}</button>`;
 const alert=$('#sync-alert');if(!alert)return;
 if(kind==='conflict'&&progressSync.conflict){
  const remote=progressSync.conflict,local=state;
  const summary=x=>`${x?.history?.length??0} sessões concluídas · ${x?.active?Object.keys(x.active.answers??{}).length+' respostas na sessão em andamento':'sem sessão em andamento'}`;
  alert.innerHTML=`<section class="note amber sync-conflict" role="alert"><h3>Há progresso diferente nos dois computadores.</h3><p>Escolha qual versão continuar. Esta escolha sincroniza o progresso inteiro, incluindo redação e histórico. Guardaremos cópias das duas versões neste navegador.</p><p><strong>Aqui:</strong> ${summary(local)}<br><strong>Na conta:</strong> ${summary(remote.state)}${remote.updatedAt?' · salvo em '+date(remote.updatedAt):''}</p><div class="button-row">${remote.state?btn('Continuar progresso da conta','sync-cloud'):''}${btn('Usar progresso deste computador','sync-local','secondary')}${btn('Ver cópias','sync-backups','secondary')}</div></section>`;
 }else if(['offline','signin','too-large','local-error'].includes(kind)){
  alert.innerHTML=`<div class="note amber sync-conflict" role="status">${kind==='signin'?'Entre com a mesma conta do ChatGPT nos dois computadores para sincronizar.':kind==='local-error'?'O navegador não conseguiu guardar uma cópia local. Mantenha a página aberta.':'As alterações continuam neste computador. Aguarde “Sincronizado” antes de trocar de computador.'} ${btn('Tentar sincronizar','sync-now','secondary slim')}</div>`;
 }else alert.innerHTML='';
}
async function showSyncBackups(){
 const dialog=$('#backup-dialog'),list=$('#backup-list');dialog.showModal();list.textContent='Carregando cópias…';
 const local=progressSync.localBackups();let cloud=[],failed=false;
 try{cloud=await progressSync.cloudBackups();}catch{failed=true;}
 list.innerHTML=`<p class="small muted">Recuperar uma cópia troca o progresso inteiro. A versão atual será guardada neste navegador antes da troca.</p><h3>Cópias neste computador</h3>${local.length?local.map((b,i)=>`<div class="backup-row"><span>${esc(b.label)}<small>${date(b.at)} · ${b.state.history.length} sessões</small></span>${btn('Recuperar','restore-local','secondary slim',`data-revision="${i}"`)}</div>`).join(''):'<p class="small muted">Nenhuma cópia de recuperação local.</p>'}<h3>Cópias anteriores da conta</h3>${failed?'<p class="small muted">Não foi possível consultar a conta. Tente novamente quando estiver conectado.</p>':cloud.length?cloud.map(b=>`<div class="backup-row"><span>Versão ${b.revision}<small>${date(b.updatedAt)}</small></span>${btn('Recuperar','restore-cloud','secondary slim',`data-revision="${b.revision}"`)}</div>`).join(''):'<p class="small muted">As últimas 20 versões ficarão disponíveis após os próximos salvamentos.</p>'}`;
}
// Controls also follow navigations and question redraws, without resetting inputs.
new MutationObserver(()=>{if(!$('#sync-status')?.firstElementChild)renderSyncStatus();}).observe($('#app'),{childList:true,subtree:true});

